private async Task LoadShipmentAsync()
{
    CancelPending();

    _lastLoadedTrackingNumber = TrackingNumber;
    _shipment = null;
    _errorMessage = null;
    _loading = true;
    StateHasChanged();

    var cts = new CancellationTokenSource();
    _cts = cts;

    try
    {
        _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cts.Token);
    }
    catch (OperationCanceledException) when (cts.IsCancellationRequested)
    {
        // Request was cancelled (navigation or dispose) — don't update UI.
        return;
    }
    catch (OperationCanceledException)
    {
        Logger.LogWarning("Request for shipment {TrackingNumber} timed out.", TrackingNumber);
        _errorMessage = "The request timed out. Please try again.";
    }
    catch (TimeoutException)
    {
        Logger.LogWarning("Request for shipment {TrackingNumber} timed out.", TrackingNumber);
        _errorMessage = "The request timed out. Please try again.";
    }
    catch (KeyNotFoundException)
    {
        Logger.LogWarning("Shipment {TrackingNumber} not found.", TrackingNumber);
        _errorMessage = $"Shipment '{TrackingNumber}' was not found.";
    }
    catch (Exception ex)
    {
        Logger.LogError(ex, "Error loading shipment {TrackingNumber}.", TrackingNumber);
        _errorMessage = "Something went wrong while loading shipment details. Please try again.";
    }
    finally
    {
        _loading = false;
        StateHasChanged();
    }
}

